def stabilite(variables, modele_cls=LinearRegression, n_tirages=30, **kw):
    """Ré-estime le modèle sur n_tirages moitiés de train_e tirées au hasard ;
    renvoie la moyenne et l'écart type de chaque coefficient (kw : paramètres du modèle, par ex. alpha)."""
    coefs = [modele_cls(**kw).fit(moitie[variables], moitie["Energie"]).coef_
             for moitie in (train_e.sample(frac=0.5, random_state=k) for k in range(n_tirages))]
    coefs = np.array(coefs)
    return pd.DataFrame({"moyenne": coefs.mean(axis=0), "écart type": coefs.std(axis=0)}, index=variables).round(2)

